use serde_json::{json, Value};
use ulw_loop_core::quality_gate::{validate_quality_gate, ValidateQualityGateOptions};
use ulw_loop_core::quality_gate_artifacts::RealQualityGateFs;
use ulw_loop_core::surface::UlwLoopToolkitSurface;

fn gate(manual: Value) -> Value { json!({"manualQa":manual,"gateReview":{"by":"category:deep","recommendation":"APPROVE","evidence":"review","reportPath":"report.txt","blockers":[]},"iteration":{"fullRerun":true,"status":"passed","rerunCommands":["test"],"evidence":"rerun"},"criteriaCoverage":{"totalCriteria":1,"passCount":1,"originalIntent":"intent","desiredOutcome":"outcome","userOutcomeReview":"review","adversarialClassesCovered":["none"]}}) }
fn opts() -> &'static ValidateQualityGateOptions<'static> { Box::leak(Box::new(ValidateQualityGateOptions { repo_root: None, fs: Some(Box::leak(Box::new(RealQualityGateFs))), current_attempt_dir: None, reviewer_surface: Some(UlwLoopToolkitSurface::OmoSenpi) })) }

#[test] fn empty_artifact_reference_reports_only_array_item_defect() { let value=gate(json!({"by":"main-session","status":"passed","evidence":"qa","surfaceEvidence":[{"id":"surface","criterionRef":"C001","surface":"cli","invocation":"run","verdict":"passed","artifactRefs":[""]}],"adversarialCases":[{"id":"adv","criterionRef":"C001","scenario":"scenario","expectedBehavior":"reject","verdict":"passed","artifactRefs":[]}],"artifactRefs":[{"id":"artifact","kind":"cli-transcript","description":"artifact","path":"artifact.txt"}]})); let options=opts(); let err=validate_quality_gate(&value,Some(options)).unwrap_err(); let details=err.details.unwrap(); let fields=details["fields"].as_array().unwrap().clone(); assert_eq!(fields.iter().filter(|f| f["field"]=="manualQa.surfaceEvidence[0].artifactRefs").count(),1); }
#[test] fn malformed_artifact_does_not_derive_downstream_defects() { let value=gate(json!({"by":"main-session","status":"passed","evidence":"qa","surfaceEvidence":[],"adversarialCases":[],"artifactRefs":[null]})); let options=opts(); let err=validate_quality_gate(&value,Some(options)).unwrap_err(); let details=err.details.unwrap(); let fields=details["fields"].as_array().unwrap(); assert_eq!(fields.iter().filter(|f| f["field"].as_str().unwrap().starts_with("manualQa.artifactRefs[0]")).count(),1); assert_eq!(fields[0]["field"],"manualQa.artifactRefs[0]"); }
#[test] fn invalid_artifact_kind_does_not_derive_compatibility_defects() { let value=gate(json!({"by":"main-session","status":"passed","evidence":"qa","surfaceEvidence":[{"id":"surface","criterionRef":"C001","surface":"data","invocation":"run","verdict":"passed","artifactRefs":["artifact"]}],"adversarialCases":[{"id":"adv","criterionRef":"C001","scenario":"scenario","expectedBehavior":"reject","verdict":"passed","artifactRefs":[]}],"artifactRefs":[{"id":"artifact","kind":"invalid","description":"artifact","path":"artifact.txt"}]})); let options=opts(); let err=validate_quality_gate(&value,Some(options)).unwrap_err(); let details=err.details.unwrap(); let fields=details["fields"].as_array().unwrap(); let labels:Vec<_>=fields.iter().map(|f|f["field"].as_str().unwrap()).collect(); assert!(labels.contains(&"manualQa.artifactRefs[0].kind")); assert!(!labels.contains(&"manualQa.surfaceEvidence")); assert!(!labels.contains(&"manualQa.surfaceEvidence[0].artifactRefs")); }
#[test] fn empty_gate_reports_each_missing_section_once() { let options=opts(); let err=validate_quality_gate(&json!({}),Some(options)).unwrap_err(); let details=err.details.unwrap(); let fields=details["fields"].as_array().unwrap(); let labels:Vec<_>=fields.iter().map(|f|f["field"].as_str().unwrap()).collect(); for label in ["manualQa","gateReview","iteration","criteriaCoverage"] { assert!(labels.contains(&label)); } let unique:std::collections::BTreeSet<_>=labels.iter().collect(); assert_eq!(unique.len(),labels.len()); }
#[test] fn not_applicable_surface_verdict_reports_once() { let value=gate(json!({"by":"main-session","status":"passed","evidence":"qa","surfaceEvidence":[{"id":"surface","criterionRef":"C001","surface":"cli","invocation":"run","verdict":"not_applicable","artifactRefs":[]}],"adversarialCases":[{"id":"adv","criterionRef":"C001","scenario":"scenario","expectedBehavior":"reject","verdict":"passed","artifactRefs":[]}],"artifactRefs":[{"id":"artifact","kind":"cli-transcript","description":"artifact","path":"artifact.txt"}]})); let options=opts(); let err=validate_quality_gate(&value,Some(options)).unwrap_err(); let details=err.details.unwrap(); let fields=details["fields"].as_array().unwrap(); assert_eq!(fields.iter().filter(|f|f["field"]=="manualQa.surfaceEvidence[0].verdict").count(),1); }
